const items = $input.all();

const rows = items.map(item => {
  const d = item.json;
  return `<tr>
    <td>${d.payee}</td>
    <td>${d.earlierDate} — $${d.earlierAmount.toFixed(2)}</td>
    <td>${d.laterDate} — $${d.laterAmount.toFixed(2)}</td>
  </tr>`;
}).join('\n');

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Repeating Payees</title>
<style>
  body { font-family: Arial, sans-serif; margin: 40px; color: #222; }
  h1 { font-size: 20px; }
  table { border-collapse: collapse; width: 100%; max-width: 800px; }
  th, td { border: 1px solid #ddd; padding: 8px 12px; font-size: 14px; }
  th { background: #f4f4f4; text-align: left; }
  tr:nth-child(even) { background: #fafafa; }
</style>
</head>
<body>
  <h1>Recurring Payees — Last 2 Months</h1>
  <table>
    <thead>
      <tr><th>Payee</th><th>Month 1</th><th>Month 2</th></tr>
    </thead>
    <tbody>
      ${rows}
    </tbody>
  </table>
</body>
</html>
`;

return [{ json: { html } }];

const httpItem = $input.first().json;
const transactions = (httpItem.data && httpItem.data.transactions) || [];

console.log(transactions);

const month2 = $('Set Budget and Date Parameters').first().json.month2; // most recent full month
const month1 = $('Set Budget and Date Parameters').first().json.month1; // month before that

function getMonth(dateStr) {
  return dateStr.substring(0, 7); // 'YYYY-MM'
}

// Group transactions by payee, then by month
const payeeMonths = {};

for (const txn of transactions) {
  if (txn.deleted) continue;
  const txnMonth = getMonth(txn.date);

  if (txnMonth !== month1 && txnMonth !== month2) continue;

  const payee = txn.payee_name || 'Unknown Payee';
  if (!payeeMonths[payee]) payeeMonths[payee] = {};
  if (!payeeMonths[payee][txnMonth]) payeeMonths[payee][txnMonth] = [];
  payeeMonths[payee][txnMonth].push(txn);
}

const results = [];

// One row per payee that appears in BOTH months
for (const payee of Object.keys(payeeMonths).sort()) {
  const months = payeeMonths[payee];
  if (months[month1] && months[month2]) {
    // If a payee has multiple transactions in the same month, just take the first one
    const txn1 = months[month1][0];
    const txn2 = months[month2][0];

    results.push({
      json: {
        payee: payee,
        earlierDate: txn1.date,
        earlierAmount: Number((txn1.amount / 1000).toFixed(2)),
        laterDate: txn2.date,
        laterAmount: Number((txn2.amount / 1000).toFixed(2))
      }
    });
  }
}

return results;
